import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.eventbus.Subscribe;

public class BrutusBoardReader
{
    private static final String BRUTUS = "Brutus";
    private static final String DEMONIC_BRUTUS = "Demonic Brutus";
    private static final Set<Integer> SCOREBOARD_OBJECTS = Set.of(
        ObjectID.COWBOSS_SCOREBOARD_MULTI, ObjectID.COWBOSS_SCOREBOARD, ObjectID.COWBOSS_SCOREBOARD_UBER);
    private static final Map<String, Integer> KILL_COUNT_VARP_BY_BOSS = Map.of(
        BRUTUS, VarPlayerID.TOTAL_COWBOSS_KILLS,
        DEMONIC_BRUTUS, VarPlayerID.TOTAL_COWBOSS_HARDMODE_KILLS);

    private final Client client;
    private final BoardTimesSender boardTimesSender;
    private final ScoreboardClicks scoreboardClicks = new ScoreboardClicks();
    private String bossOfBoardOpenedThisTick;

    @Inject
    BrutusBoardReader(Client client, BoardTimesSender boardTimesSender)
    {
        this.client = client;
        this.boardTimesSender = boardTimesSender;
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked menuOptionClicked)
    {
        if (!SCOREBOARD_OBJECTS.contains(menuOptionClicked.getId()))
        {
            return;
        }

        switch (menuOptionClicked.getMenuAction())
        {
            case GAME_OBJECT_FIRST_OPTION:
                scoreboardClicks.clicked(BRUTUS, client.getTickCount());
                break;
            case GAME_OBJECT_SECOND_OPTION:
                scoreboardClicks.clicked(DEMONIC_BRUTUS, client.getTickCount());
                break;
            default:
                break;
        }
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded widgetLoaded)
    {
        if (widgetLoaded.getGroupId() == InterfaceID.COWBOSS_SCOREBOARD)
        {
            bossOfBoardOpenedThisTick = scoreboardClicks.bossOfBoardOpenedAt(client.getTickCount());
        }
    }

    @Subscribe
    public void onGameTick(GameTick gameTick)
    {
        String boss = bossOfBoardOpenedThisTick;
        bossOfBoardOpenedThisTick = null;
        if (boss == null || !showsKillCountOf(boss))
        {
            return;
        }

        List<BoardTime> boardTimes = new ArrayList<>();
        BoardTime.ofShownTime(boss, ANY_TEAM_SIZE, WHOLE_RUN,
            BoardWidgets.textOf(client, InterfaceID.CowbossScoreboard.PBT_CONTENT)).ifPresent(boardTimes::add);
        boardTimesSender.send(boardTimes);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged gameStateChanged)
    {
        if (gameStateChanged.getGameState() == GameState.LOGIN_SCREEN || gameStateChanged.getGameState() == GameState.HOPPING)
        {
            scoreboardClicks.clear();
            bossOfBoardOpenedThisTick = null;
        }
    }

    private boolean showsKillCountOf(String boss)
    {
        String shownKillCount = BoardWidgets.textOf(client, InterfaceID.CowbossScoreboard.PKC_CONTENT).replace(",", "");
        return shownKillCount.equals(Integer.toString(client.getVarpValue(KILL_COUNT_VARP_BY_BOSS.get(boss))));
    }
}

package com.encryptiron.boards;

import static com.encryptiron.boards.BoardTime.ANY_TEAM_SIZE;
import static com.encryptiron.boards.BoardTime.WHOLE_RUN;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import javax.inject.Inject;

import net.runelite.api.events.ScriptPreFired;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

public class JadChallengeBoardReader
{
    private static final int JAD_CHALLENGE_SETUP = 4023;
    private static final int BOARD_TEXT_ARGUMENT = 1;
    private static final Pattern LINE_BREAK = Pattern.compile("(?i)<br\\s*/?>");
    private static final Pattern CHALLENGE = Pattern.compile("TzHaar-Ket-Rak's \\w+ Challenge");
    private static final Pattern PERSONAL_BEST = Pattern.compile("Personal Best Time: (.+)");

    private final BoardTimesSender boardTimesSender;

    @Inject
    JadChallengeBoardReader(BoardTimesSender boardTimesSender)
    {
        this.boardTimesSender = boardTimesSender;
    }

    @Subscribe
    public void onScriptPreFired(ScriptPreFired scriptPreFired)
    {
        if (scriptPreFired.getScriptId() != JAD_CHALLENGE_SETUP || scriptPreFired.getScriptEvent() == null)
        {
            return;
        }

        Object[] arguments = scriptPreFired.getScriptEvent().getArguments();
        if (arguments != null && arguments.length > BOARD_TEXT_ARGUMENT && arguments[BOARD_TEXT_ARGUMENT] instanceof String)
        {
            boardTimesSender.send(readChallenges((String) arguments[BOARD_TEXT_ARGUMENT]));
        }
    }

    private static List<BoardTime> readChallenges(String boardText)
    {
        List<BoardTime> boardTimes = new ArrayList<>();
        String challenge = null;
        for (String taggedLine : LINE_BREAK.split(boardText))
        {
            String line = Text.removeTags(taggedLine).trim();
            Matcher personalBest = PERSONAL_BEST.matcher(line);
            if (CHALLENGE.matcher(line).matches())
            {
                challenge = line;
            }
            else if (challenge != null && personalBest.matches())
            {
                BoardTime.ofShownTime(challenge, ANY_TEAM_SIZE, WHOLE_RUN, personalBest.group(1)).ifPresent(boardTimes::add);
                challenge = null;
            }
        }
        return boardTimes;
    }
}

package com.encryptiron.boards;

class ModeTabClicks
{
    private int clicksSinceBoardOpened;
    private boolean inDoubtUntilClosed;

    void clicked()
    {
        clicksSinceBoardOpened++;
        if (clicksSinceBoardOpened > 1)
        {
            inDoubtUntilClosed = true;
        }
    }

    void boardOpened()
    {
        clicksSinceBoardOpened = 0;
    }

    void boardClosed()
    {
        clicksSinceBoardOpened = 0;
        inDoubtUntilClosed = false;
    }

    boolean isShownModeCertain()
    {
        return clicksSinceBoardOpened == 0 && !inDoubtUntilClosed;
    }
}

package com.encryptiron.boards;

import static com.encryptiron.boards.BoardTime.OVERALL_TIME;
import static com.encryptiron.boards.BoardTime.WHOLE_RUN;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InterfaceID.ToaScoreboard;
import net.runelite.api.gameval.InterfaceID.TobScoreboard;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

public class RaidBoardReader
{
    private static final int TOB_SCOREBOARD_TAB_SELECT = 4493;
    private static final int TOA_SCOREBOARD_TAB_SELECT = 6774;
    private static final int TAB_ARGUMENT = 4;

    private final Client client;
    private final BoardTimesSender boardTimesSender;
    private final List<RaidBoard> raidBoards = List.of(
        new RaidBoard(InterfaceID.TOB_SCOREBOARD, VarbitID.TOB_SCOREBOARD_TAB, TOB_SCOREBOARD_TAB_SELECT,
            Map.of(0, "Theatre of Blood", 1, "Theatre of Blood: Entry Mode", 2, "Theatre of Blood: Hard Mode"),
            new int[] {
                TobScoreboard.DATA_SOLO_P_R, TobScoreboard.DATA_2MAN_P_R, TobScoreboard.DATA_3MAN_P_R,
                TobScoreboard.DATA_4MAN_P_R, TobScoreboard.DATA_5MAN_P_R
            },
            new int[] {
                TobScoreboard.DATA_SOLO_P_O, TobScoreboard.DATA_2MAN_P_O, TobScoreboard.DATA_3MAN_P_O,
                TobScoreboard.DATA_4MAN_P_O, TobScoreboard.DATA_5MAN_P_O
            }),
        new RaidBoard(InterfaceID.TOA_SCOREBOARD, VarbitID.TOA_SCOREBOARD_TAB, TOA_SCOREBOARD_TAB_SELECT,
            Map.of(0, "Tombs of Amascut", 1, "Tombs of Amascut: Entry Mode", 2, "Tombs of Amascut: Expert Mode"),
            new int[] {
                ToaScoreboard.DATA_SOLO_P_R, ToaScoreboard.DATA_2MAN_P_R, ToaScoreboard.DATA_3MAN_P_R, ToaScoreboard.DATA_4MAN_P_R,
                ToaScoreboard.DATA_5MAN_P_R, ToaScoreboard.DATA_6MAN_P_R, ToaScoreboard.DATA_7MAN_P_R, ToaScoreboard.DATA_8MAN_P_R
            },
            new int[] {
                ToaScoreboard.DATA_SOLO_P_O, ToaScoreboard.DATA_2MAN_P_O, ToaScoreboard.DATA_3MAN_P_O, ToaScoreboard.DATA_4MAN_P_O,
                ToaScoreboard.DATA_5MAN_P_O, ToaScoreboard.DATA_6MAN_P_O, ToaScoreboard.DATA_7MAN_P_O, ToaScoreboard.DATA_8MAN_P_O
            }));

    @Inject
    RaidBoardReader(Client client, BoardTimesSender boardTimesSender)
    {
        this.client = client;
        this.boardTimesSender = boardTimesSender;
    }

    @Subscribe
    public void onScriptPreFired(ScriptPreFired scriptPreFired)
    {
        for (RaidBoard raidBoard : raidBoards)
        {
            if (scriptPreFired.getScriptId() == raidBoard.tabSelectScript && !isAlreadySelectedTab(scriptPreFired, raidBoard))
            {
                raidBoard.modeTabClicks.clicked();
            }
        }
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded widgetLoaded)
    {
        for (RaidBoard raidBoard : raidBoards)
        {
            if (widgetLoaded.getGroupId() == raidBoard.interfaceId)
            {
                raidBoard.modeTabClicks.boardOpened();
                raidBoard.openedThisTick = true;
            }
        }
    }

    @Subscribe
    public void onGameTick(GameTick gameTick)
    {
        for (RaidBoard raidBoard : raidBoards)
        {
            if (!BoardWidgets.isOpen(client, raidBoard.interfaceId))
            {
                raidBoard.modeTabClicks.boardClosed();
            }
            else if (raidBoard.openedThisTick && raidBoard.modeTabClicks.isShownModeCertain())
            {
                readBoard(raidBoard);
            }
            raidBoard.openedThisTick = false;
        }
    }

    private boolean isAlreadySelectedTab(ScriptPreFired scriptPreFired, RaidBoard raidBoard)
    {
        Object[] arguments = scriptPreFired.getScriptEvent() == null ? null : scriptPreFired.getScriptEvent().getArguments();
        return arguments != null && arguments.length > TAB_ARGUMENT
            && Integer.valueOf(client.getVarbitValue(raidBoard.tabVarbit)).equals(arguments[TAB_ARGUMENT]);
    }

    private void readBoard(RaidBoard raidBoard)
    {
        String content = raidBoard.contentByTab.get(client.getVarbitValue(raidBoard.tabVarbit));
        if (content == null)
        {
            return;
        }

        List<BoardTime> boardTimes = new ArrayList<>();
        for (int players = 1; players <= raidBoard.challengeTimeComponents.length; players++)
        {
            String teamSize = BoardTime.teamSizeOf(players);
            BoardTime.ofShownTime(content, teamSize, WHOLE_RUN,
                BoardWidgets.textOf(client, raidBoard.challengeTimeComponents[players - 1])).ifPresent(boardTimes::add);
            BoardTime.ofShownTime(content, teamSize, OVERALL_TIME,
                BoardWidgets.textOf(client, raidBoard.overallTimeComponents[players - 1])).ifPresent(boardTimes::add);
        }
        boardTimesSender.send(boardTimes);
    }

    private static class RaidBoard
    {
        private final int interfaceId;
        private final int tabVarbit;
        private final int tabSelectScript;
        private final Map<Integer, String> contentByTab;
        private final int[] challengeTimeComponents;
        private final int[] overallTimeComponents;
        private final ModeTabClicks modeTabClicks = new ModeTabClicks();
        private boolean openedThisTick;

        private RaidBoard(int interfaceId, int tabVarbit, int tabSelectScript, Map<Integer, String> contentByTab,
            int[] challengeTimeComponents, int[] overallTimeComponents)
        {
            this.interfaceId = interfaceId;
            this.tabVarbit = tabVarbit;
            this.tabSelectScript = tabSelectScript;
            this.contentByTab = contentByTab;
            this.challengeTimeComponents = challengeTimeComponents;
            this.overallTimeComponents = overallTimeComponents;
        }
    }
}

package com.encryptiron.boards;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

class ScoreboardClicks
{
    private static final int TICKS_A_CLICK_STAYS_IN_DOUBT = 10;

    private final Set<String> bossesClickedSinceLastBoard = new HashSet<>();
    private final Map<String, Integer> lastClickTickByBoss = new HashMap<>();

    void clicked(String boss, int tick)
    {
        bossesClickedSinceLastBoard.add(boss);
        lastClickTickByBoss.put(boss, tick);
    }

    String bossOfBoardOpenedAt(int tick)
    {
        Set<String> possibleBosses = new HashSet<>(bossesClickedSinceLastBoard);
        bossesClickedSinceLastBoard.clear();
        if (possibleBosses.isEmpty())
        {
            return null;
        }

        lastClickTickByBoss.forEach((boss, clickTick) -> {
            if (tick - clickTick <= TICKS_A_CLICK_STAYS_IN_DOUBT)
            {
                possibleBosses.add(boss);
            }
        });
        return possibleBosses.size() == 1 ? possibleBosses.iterator().next() : null;
    }

    void clear()
    {
        bossesClickedSinceLastBoard.clear();
        lastClickTickByBoss.clear();
    }
}

package com.encryptiron.chat;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;

import javax.inject.Inject;
import javax.inject.Singleton;

import com.encryptiron.ValianceConfig;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatLineBuffer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.IconID;
import net.runelite.api.MessageNode;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
public class ClanChatService
{
    public static final String CLAN_NAME = "Valiance";

    private static final int TICKS_OUTSIDE_CLAN_BEFORE_DISCONNECT = 10;

    private static final int TICKS_BETWEEN_CONNECT_ATTEMPTS = 10;

    private static final int MAX_REPORTED_MESSAGE_AGE_SECONDS = 10;

    private static final Pattern NON_ESCAPE_TAG = Pattern.compile("<(?!lt>|gt>)[^>]*>");
    private static final Pattern NON_NAME_CHARACTER = Pattern.compile("[^A-Za-z0-9 _-]");

    private static final String HISTORY_END_MESSAGE = "<col=7f7f7f>End of recent clan chat</col>";

    private static final int MAX_SECONDS_BETWEEN_SAME_LINE = 60;

    private static final String SHARE_CLAN_CHAT_REMINDER =
        "Turn on <col=ffff00>Share my clan chat</col> in the Valiance plugin settings so clanmates who log in later can see your messages.";

    @Inject
    private Client client;

    @Inject
    private ValianceSocket socket;

    @Inject
    private ValianceConfig config;

    @Inject
    private RankIcons rankIcons;

    private int ticksOutsideClan;
    private int ticksUntilConnectAttempt;
    private boolean historyRequestedThisLogin;
    private boolean addingServerLines;

    public void startUp()
    {
        socket.setHandler("welcome", this::onWelcome);
        socket.setHandler("chat_message", this::onServerLine);
    }

    public void shutDown()
    {
        socket.stop();
        ticksOutsideClan = 0;
        ticksUntilConnectAttempt = 0;
        historyRequestedThisLogin = false;
    }

    public static boolean isValiance(ClanChannel channel)
    {
        return channel != null && CLAN_NAME.equalsIgnoreCase(Text.removeTags(channel.getName()).trim());
    }

    public ChatMessageType broadcastType()
    {
        return isValiance(client.getClanChannel())
            ? ChatMessageType.CLAN_MESSAGE
            : ChatMessageType.CLAN_GUEST_MESSAGE;
    }

    private boolean isInValianceChannel()
    {
        return isValiance(client.getClanChannel()) || isValiance(client.getGuestClanChannel());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGIN_SCREEN)
        {
            shutDown();
        }
    }

    @Subscribe
    public void onGameTick(GameTick tick)
    {
        if (isInValianceChannel())
        {
            ticksOutsideClan = 0;
            if (!socket.isRunning() && --ticksUntilConnectAttempt <= 0)
            {
                startSocket();
            }
        }
        else if (socket.isRunning() && ++ticksOutsideClan >= TICKS_OUTSIDE_CLAN_BEFORE_DISCONNECT)
        {
            socket.stop();
        }
    }

    private void startSocket()
    {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null || localPlayer.getName() == null)
        {
            return;
        }

        RuneScapeProfileType profileType = RuneScapeProfileType.getCurrent(client);
        if (profileType != RuneScapeProfileType.STANDARD)
        {
            return;
        }

        JsonObject handshake = new JsonObject();
        handshake.addProperty("type", "hello");
        handshake.addProperty("account_hash", Long.toString(client.getAccountHash()));
        handshake.addProperty("rsn", Text.sanitize(localPlayer.getName()));
        handshake.addProperty("profile_type", profileType.name());
        handshake.addProperty("account_type", client.getVarbitValue(VarbitID.IRONMAN));

        if (rankIcons.getRanksVersion() != null)
        {
            handshake.addProperty("ranks_version", rankIcons.getRanksVersion());
        }
        if (rankIcons.getIconsVersion() != null)
        {
            handshake.addProperty("icons_version", rankIcons.getIconsVersion());
        }

        if (!historyRequestedThisLogin)
        {
            handshake.addProperty("history", config.clanChatHistoryCount());
            historyRequestedThisLogin = true;
        }

        ticksUntilConnectAttempt = TICKS_BETWEEN_CONNECT_ATTEMPTS;
        socket.start(handshake);
    }

    private Map<String, List<Integer>> chatboxLineTimesByKey(ChatMessageType... types)
    {
        Map<String, List<Integer>> lines = new HashMap<>();
        for (ChatMessageType type : types)
        {
            ChatLineBuffer buffer = client.getChatLineMap().get(type.getType());
            if (buffer == null)
            {
                continue;
            }

            for (MessageNode node : buffer.getLines())
            {
                if (node != null)
                {
                    lines.computeIfAbsent(plainNameAndMessage(node.getName(), node.getValue()), key -> new ArrayList<>())
                        .add(node.getTimestamp());
                }
            }
        }
        return lines;
    }

    private static String plainNameAndMessage(String name, String message)
    {
        String plainName = name == null ? "" : Text.sanitize(name).toLowerCase(Locale.ROOT);
        String plainMessage = message == null ? "" : Text.removeTags(message);
        return plainName + "\n" + plainMessage;
    }

    private static boolean isAlreadyInChatbox(Map<String, List<Integer>> chatbox, String name, String message, long sentAtMillis)
    {
        List<Integer> times = chatbox.get(plainNameAndMessage(name, message));
        if (times == null)
        {
            return false;
        }

        long sentAt = sentAtMillis / 1000;
        for (int time : times)
        {
            if (Math.abs(time - sentAt) <= MAX_SECONDS_BETWEEN_SAME_LINE)
            {
                return true;
            }
        }
        return false;
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (addingServerLines || !config.shareClanChat())
        {
            return;
        }

        ClanChannel channel;
        if (event.getType() == ChatMessageType.CLAN_CHAT)
        {
            channel = client.getClanChannel();
        }
        else if (event.getType() == ChatMessageType.CLAN_GUEST_CHAT)
        {
            channel = client.getGuestClanChannel();
        }
        else
        {
            return;
        }

        Player localPlayer = client.getLocalPlayer();
        if (!isValiance(channel) || localPlayer == null || localPlayer.getName() == null)
        {
            return;
        }

        if (!Text.sanitize(event.getName()).equalsIgnoreCase(Text.sanitize(localPlayer.getName())))
        {
            return;
        }

        if (Instant.now().getEpochSecond() - event.getTimestamp() > MAX_REPORTED_MESSAGE_AGE_SECONDS)
        {
            return;
        }

        JsonObject chat = new JsonObject();
        chat.addProperty("type", "chat");
        chat.addProperty("message", event.getMessage());
        socket.send(chat);
    }

    private void onWelcome(JsonObject welcome)
    {
        rankIcons.onWelcome(welcome);
        replayHistory(welcome);
        remindToShareClanChat();
    }

    private void remindToShareClanChat()
    {
        if (config.shareClanChatReminderShown() || config.shareClanChat() || !isInValianceChannel())
        {
            return;
        }

        config.shareClanChatReminderShown(true);
        addingServerLines = true;
        try
        {
            client.addChatMessage(broadcastType(), "", SHARE_CLAN_CHAT_REMINDER, CLAN_NAME);
        }
        finally
        {
            addingServerLines = false;
        }
    }

    private void replayHistory(JsonObject welcome)
    {
        JsonElement historyElement = welcome.get("history");
        if (historyElement == null || !historyElement.isJsonArray())
        {
            return;
        }

        JsonArray history = historyElement.getAsJsonArray();
        if (history.size() == 0 || !isInValianceChannel())
        {
            return;
        }

        ChatMessageType chatType = isValiance(client.getClanChannel())
            ? ChatMessageType.CLAN_CHAT
            : ChatMessageType.CLAN_GUEST_CHAT;

        ChatMessageType serverLineType = broadcastType();
        Map<String, List<Integer>> chatbox = chatboxLineTimesByKey(chatType, serverLineType);
        boolean added = false;

        addingServerLines = true;
        try
        {
            for (JsonElement element : history)
            {
                if (!element.isJsonObject())
                {
                    continue;
                }

                JsonObject entry = element.getAsJsonObject();
                boolean serverLine = "chat_message".equals(ValianceSocket.getString(entry, "type"));
                JsonElement sentAt = entry.get("sent_at");
                if (sentAt != null && sentAt.isJsonPrimitive() && isAlreadyInChatbox(chatbox,
                    serverLine ? "" : ValianceSocket.getString(entry, "rsn"),
                    ValianceSocket.getString(entry, "message"),
                    sentAt.getAsLong()))
                {
                    continue;
                }

                if (serverLine)
                {
                    addServerLine(serverLineType, entry);
                }
                else
                {
                    addReplayedPlayerLine(chatType, entry);
                }
                added = true;
            }

            if (added)
            {
                client.addChatMessage(serverLineType, "", HISTORY_END_MESSAGE, CLAN_NAME);
            }
        }
        finally
        {
            addingServerLines = false;
        }
    }

    private void onServerLine(JsonObject line)
    {
        addingServerLines = true;
        try
        {
            addServerLine(broadcastType(), line);
        }
        finally
        {
            addingServerLines = false;
        }
    }

    private void addServerLine(ChatMessageType type, JsonObject line)
    {
        String message = ValianceSocket.getString(line, "message");
        if (message == null)
        {
            return;
        }

        MessageNode node = client.addChatMessage(type, "", message, CLAN_NAME);
        if (node == null)
        {
            return;
        }

        JsonElement sentAt = line.get("sent_at");
        if (sentAt != null && sentAt.isJsonPrimitive())
        {
            node.setTimestamp((int) (sentAt.getAsLong() / 1000));
        }
    }

    private static String accountTypeIconTag(JsonElement accountType)
    {
        if (accountType == null || !accountType.isJsonPrimitive())
        {
            return "";
        }

        IconID icon;
        switch (accountType.getAsInt())
        {
            case 1:
                icon = IconID.IRONMAN;
                break;
            case 2:
                icon = IconID.ULTIMATE_IRONMAN;
                break;
            case 3:
                icon = IconID.HARDCORE_IRONMAN;
                break;
            case 4:
                icon = IconID.GROUP_IRONMAN;
                break;
            case 5:
                icon = IconID.HARDCORE_GROUP_IRONMAN;
                break;
            case 6:
                icon = IconID.UNRANKED_GROUP_IRONMAN;
                break;
            default:
                return "";
        }
        return "<img=" + icon.getIndex() + ">";
    }

    private void addReplayedPlayerLine(ChatMessageType chatType, JsonObject entry)
    {
        String name = ValianceSocket.getString(entry, "rsn");
        String message = ValianceSocket.getString(entry, "message");
        JsonElement sentAt = entry.get("sent_at");
        if (name == null || message == null || sentAt == null || !sentAt.isJsonPrimitive())
        {
            return;
        }

        String cleanName = NON_NAME_CHARACTER.matcher(Text.removeTags(name)).replaceAll("");
        String cleanMessage = NON_ESCAPE_TAG.matcher(message).replaceAll("");
        if (cleanName.isEmpty() || cleanMessage.isEmpty())
        {
            return;
        }

        String nameWithIcon = accountTypeIconTag(entry.get("account_type")) + cleanName;

        MessageNode node = client.addChatMessage(chatType, nameWithIcon, cleanMessage, CLAN_NAME);
        if (node != null)
        {
            node.setTimestamp((int) (sentAt.getAsLong() / 1000));
        }
    }
}

package com.encryptiron.chat;

import java.util.HashSet;
