@Slf4j
@Singleton
public class RankIcons
{
    private static final String CHAT_MESSAGE_BUILDING = "chatMessageBuilding";
    private static final String SAVED_RANKS_FILE_NAME = "ranks.json";

    private static final Pattern IMG_TAG = Pattern.compile("<img=(\\d+)>");
    private static final int NEAR_BLACK = 0x010101;
    private static final int RANK_ICON_OFFSET_Y = 2;
    private static final Pattern NAME_SPACING = Pattern.compile("[\\s_\\u00A0]+");
    private static final List<String> GUEST_RANKS = List.of("Guest");
    private static final int RANK_SLOT_FIRST_SPRITE_ID = -760_000;
    private static final int RANK_SLOT_HEIGHT = 13;

    private static final Set<Integer> NON_RANK_ACCOUNT_ICONS = Set.of(
        IconID.PLAYER_MODERATOR.getIndex(),
        IconID.JAGEX_MODERATOR.getIndex(),
        IconID.IRONMAN.getIndex(),
        IconID.ULTIMATE_IRONMAN.getIndex(),
        IconID.HARDCORE_IRONMAN.getIndex(),
        IconID.LEAGUE.getIndex(),
        IconID.GROUP_IRONMAN.getIndex(),
        IconID.HARDCORE_GROUP_IRONMAN.getIndex(),
        IconID.UNRANKED_GROUP_IRONMAN.getIndex()
    );

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ChatIconManager chatIconManager;

    @Inject
    private ValianceSocket socket;

    @Inject
    private Gson gson;

    @Inject
    private ScheduledExecutorService executor;

    private static class RankIcon
    {
        final int iconId;
        final List<IndexedSprite> frames;
        final List<BufferedImage> images;
        final List<Integer> delays;
        int frame;
        long nextFrameAt;

        RankIcon(int iconId, List<IndexedSprite> frames, List<BufferedImage> images, List<Integer> delays)
        {
            this.iconId = iconId;
            this.frames = frames;
            this.images = images;
            this.delays = delays;
        }
    }

    private static class RankSlotSprite
    {
        final List<RankIcon> icons;
        final int width;
        final int height;
        final Map<String, Integer> spriteIdsByFrames = new HashMap<>();

        RankSlotSprite(List<RankIcon> icons)
        {
            this.icons = icons;
            int slotWidth = 0;
            int slotHeight = RANK_SLOT_HEIGHT;
            for (RankIcon icon : icons)
            {
                slotWidth += widestFrame(icon);
                for (BufferedImage image : icon.images)
                {
                    slotHeight = Math.max(slotHeight, image.getHeight());
                }
            }
            this.width = slotWidth;
            this.height = slotHeight;
        }
    }

    static class RankSlot
    {
        final int spriteId;
        final int width;
        final int height;
        final String name;

        RankSlot(int spriteId, int width, int height, String name)
        {
            this.spriteId = spriteId;
            this.width = width;
            this.height = height;
            this.name = name;
        }
    }

    private Map<String, List<String>> members = Collections.emptyMap();
    private final Map<String, RankIcon> icons = new HashMap<>();
    private final Map<String, RankSlotSprite> rankSlotSprites = new HashMap<>();
    private int nextRankSlotSpriteId = RANK_SLOT_FIRST_SPRITE_ID;
    private static final Map<String, Integer> CHAT_ICON_ID_BY_RANK = new HashMap<>();
    private JsonObject ranksJson;
    private JsonObject iconsJson;
    private int ranksRevision;
    private int iconsGeneration;
    private boolean iconSpritesWereMissing;

    private volatile String ranksVersion;
    private Filepath savedRanksFile;
    private volatile String iconsVersion;

    public void startUp(Filepath dataDirectory)
    {
        savedRanksFile = dataDirectory.joinSegment(SAVED_RANKS_FILE_NAME);
        socket.setHandler("ranks", body -> applyRanks(body, true));
        socket.setHandler("icons", body -> applyIcons(body, true));
        executor.execute(this::loadSaved);
    }

    public void shutDown()
    {
        clientThread.invoke(this::clearRankSlots);
    }

    public String getRanksVersion()
    {
        return ranksVersion;
    }

    public String getIconsVersion()
    {
        return iconsVersion;
    }

    public void onWelcome(JsonObject welcome)
    {
        JsonElement ranks = welcome.get("ranks");
        if (ranks != null && ranks.isJsonObject())
        {
            applyRanks(ranks.getAsJsonObject(), true);
        }

        JsonElement iconsElement = welcome.get("icons");
        if (iconsElement != null && iconsElement.isJsonObject())
        {
            applyIcons(iconsElement.getAsJsonObject(), true);
        }
    }

    private void loadSaved()
    {
        if (savedRanksFile == null || !savedRanksFile.exists())
        {
            return;
        }

        JsonObject saved;
        try (var reader = savedRanksFile.openReader())
        {
            saved = gson.fromJson(reader, JsonObject.class);
        }
        catch (IOException | JsonParseException ex)
        {
            log.warn("Could not read the saved Valiance ranks", ex);
            return;
        }

        if (saved == null)
        {
            return;
        }

        clientThread.invokeLater(() ->
        {
            if (ranksJson == null && saved.has("ranks") && saved.get("ranks").isJsonObject())
            {
                applyRanks(saved.getAsJsonObject("ranks"), false);
            }
            if (iconsGeneration == 0 && saved.has("icons") && saved.get("icons").isJsonObject())
            {
                applyIcons(saved.getAsJsonObject("icons"), false);
            }
        });
    }

    private void save()
    {
        JsonObject saved = new JsonObject();
        if (ranksJson != null)
        {
            saved.add("ranks", ranksJson);
        }
        if (iconsJson != null)
        {
            saved.add("icons", iconsJson);
        }

        String json = gson.toJson(saved);
        Filepath file = savedRanksFile;
        if (file == null)
        {
            return;
        }

        executor.execute(() ->
        {
            try
            {
                file.getParent().createDirectories();
                file.write(json);
            }
            catch (IOException ex)
            {
                log.warn("Could not save the Valiance ranks", ex);
            }
        });
    }

    private void applyRanks(JsonObject body, boolean fromServer)
    {
        JsonElement membersElement = body.get("members");
        if (membersElement == null || !membersElement.isJsonObject())
        {
            return;
        }

        Map<String, List<String>> next = new HashMap<>();
        for (Map.Entry<String, JsonElement> entry : membersElement.getAsJsonObject().entrySet())
        {
            if (!entry.getValue().isJsonArray())
            {
                continue;
            }

            List<String> ranks = new ArrayList<>();
            for (JsonElement rank : entry.getValue().getAsJsonArray())
            {
                if (rank.isJsonPrimitive())
                {
                    ranks.add(rank.getAsString());
                }
            }
            next.put(normaliseName(entry.getKey()), ranks);
        }

        members = next;
        ranksJson = body;
        ranksVersion = ValianceSocket.getString(body, "version");
        ranksRevision++;
        if (fromServer)
        {
            save();
        }
        client.refreshChat();
    }

    private void applyIcons(JsonObject body, boolean fromServer)
    {
        JsonElement iconsElement = body.get("icons");
        if (iconsElement == null || !iconsElement.isJsonObject())
        {
            return;
        }

        JsonObject iconsByRank = iconsElement.getAsJsonObject();
        int generation = ++iconsGeneration;
        executor.execute(() ->
        {
            Map<String, DecodedIcon> decoded = decodeIcons(iconsByRank);
            clientThread.invokeLater(() ->
            {
                if (generation != iconsGeneration)
                {
                    return true;
                }

                if (client.getGameState().getState() < GameState.LOGIN_SCREEN.getState())
                {
                    return false;
                }

                installIcons(decoded);
                iconsJson = body;
                iconsVersion = ValianceSocket.getString(body, "version");
                ranksRevision++;
                if (fromServer)
                {
                    save();
                }
                client.refreshChat();
                return true;
            });
        });
    }

    private static class DecodedIcon
    {
        final List<BufferedImage> frames = new ArrayList<>();
        final List<Integer> delays = new ArrayList<>();
    }

    private static Map<String, DecodedIcon> decodeIcons(JsonObject iconsByRank)
    {
        Map<String, DecodedIcon> decoded = new HashMap<>();
        for (Map.Entry<String, JsonElement> entry : iconsByRank.entrySet())
        {
            if (!entry.getValue().isJsonObject())
            {
                continue;
            }

            JsonObject icon = entry.getValue().getAsJsonObject();
            JsonElement frames = icon.get("frames");
            JsonElement delays = icon.get("delays");
            if (frames == null || !frames.isJsonArray() || delays == null || !delays.isJsonArray())
            {
                continue;
            }

            DecodedIcon result = new DecodedIcon();
            JsonArray frameArray = frames.getAsJsonArray();
            JsonArray delayArray = delays.getAsJsonArray();
            for (int i = 0; i < frameArray.size() && i < delayArray.size(); i++)
            {
                try
                {
                    byte[] png = Base64.getDecoder().decode(frameArray.get(i).getAsString());
                    BufferedImage image = ImageIO.read(new ByteArrayInputStream(png));
                    if (image != null)
                    {
                        result.frames.add(replacePureBlackWithNearBlack(image));
                        result.delays.add(delayArray.get(i).getAsInt());
                    }
                }
                catch (IOException | IllegalArgumentException | IllegalStateException | UnsupportedOperationException ex)
                {
                    log.warn("Skipping an unreadable frame of the {} rank icon", entry.getKey(), ex);
                }
            }

            if (!result.frames.isEmpty())
            {
                decoded.put(entry.getKey(), result);
            }
        }
        return decoded;
    }

    private static BufferedImage replacePureBlackWithNearBlack(BufferedImage source)
    {
        BufferedImage image = new BufferedImage(source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < source.getHeight(); y++)
        {
            for (int x = 0; x < source.getWidth(); x++)
            {
                int argb = source.getRGB(x, y);
                boolean opaque = (argb >>> 24) != 0;
                if (opaque && (argb & 0xFFFFFF) == 0)
                {
                    argb |= NEAR_BLACK;
                }
                image.setRGB(x, y, argb);
            }
        }
        return image;
    }

    private void installIcons(Map<String, DecodedIcon> decoded)
    {
        clearRankSlots();
        icons.clear();
        long now = System.currentTimeMillis();
        for (Map.Entry<String, DecodedIcon> entry : decoded.entrySet())
        {
            DecodedIcon icon = entry.getValue();
            int iconId = CHAT_ICON_ID_BY_RANK.computeIfAbsent(entry.getKey(), rank -> chatIconManager.reserveChatIcon());
            chatIconManager.updateChatIcon(iconId, icon.frames.get(0));

            List<IndexedSprite> frames = new ArrayList<>();
            for (BufferedImage image : icon.frames)
            {
                IndexedSprite frame = ImageUtil.getImageIndexedSprite(image, client);
                frame.setOffsetY(RANK_ICON_OFFSET_Y);
                frames.add(frame);
            }

            RankIcon rankIcon = new RankIcon(iconId, frames, icon.frames, icon.delays);
            rankIcon.nextFrameAt = now + icon.delays.get(0);
            icons.put(entry.getKey(), rankIcon);
        }
    }

    @Subscribe
    public void onClientTick(ClientTick tick)
    {
        if (icons.isEmpty())
        {
            return;
        }

        long now = System.currentTimeMillis();
        IndexedSprite[] modIcons = client.getModIcons();
        List<RankIcon> advanced = new ArrayList<>();
        for (RankIcon icon : icons.values())
        {
            if (icon.frames.size() < 2 || now < icon.nextFrameAt)
            {
                continue;
            }

            icon.frame = (icon.frame + 1) % icon.frames.size();
            icon.nextFrameAt = now + icon.delays.get(icon.frame);
            advanced.add(icon);

            int index = chatIconManager.chatIconIndex(icon.iconId);
            if (modIcons != null && index >= 0 && index < modIcons.length)
            {
                modIcons[index] = icon.frames.get(icon.frame);
            }
        }

        if (!advanced.isEmpty())
        {
            showCurrentRankSlotFrames(advanced);
        }

        lowerIconsAndRedrawOnceLoaded();
    }

    private void lowerIconsAndRedrawOnceLoaded()
    {
        IndexedSprite[] modIcons = client.getModIcons();
        boolean missing = modIcons == null;

        for (RankIcon icon : icons.values())
        {
            int index = chatIconManager.chatIconIndex(icon.iconId);
            if (modIcons == null || index < 0 || index >= modIcons.length || modIcons[index] == null)
            {
                missing = true;
                continue;
            }

            if (modIcons[index].getOffsetY() != RANK_ICON_OFFSET_Y)
            {
                modIcons[index].setOffsetY(RANK_ICON_OFFSET_Y);
            }
        }

        if (iconSpritesWereMissing && !missing)
        {
            log.debug("Valiance rank icons are back, redrawing the chat");
            client.refreshChat();
        }
        iconSpritesWereMissing = missing;
    }

    @Subscribe
    public void onScriptCallbackEvent(ScriptCallbackEvent event)
    {
        if (!CHAT_MESSAGE_BUILDING.equals(event.getEventName()))
        {
            return;
        }

        int[] intStack = client.getIntStack();
        int intStackSize = client.getIntStackSize();
        MessageNode node = client.getMessages().get(intStack[intStackSize - 1]);
        if (node == null || !isValianceClanChat(node))
        {
            return;
        }

        Object[] objectStack = client.getObjectStack();
        int objectStackSize = client.getObjectStackSize();
        Object name = objectStack[objectStackSize - 3];
        if (!(name instanceof String))
        {
            return;
        }

        objectStack[objectStackSize - 3] = rewriteName((String) name);
    }

    private boolean isValianceClanChat(MessageNode node)
    {
        ChatMessageType type = node.getType();
        if (type == ChatMessageType.CLAN_CHAT)
        {
            return ClanChatService.isValiance(client.getClanChannel());
        }
        if (type == ChatMessageType.CLAN_GUEST_CHAT)
        {
            return ClanChatService.isValiance(client.getGuestClanChannel());
        }
        return false;
    }

    private String rewriteName(String name)
    {
        StringBuilder accountIcons = new StringBuilder();
        Matcher tags = IMG_TAG.matcher(name);
        while (tags.find())
        {
            if (NON_RANK_ACCOUNT_ICONS.contains(Integer.parseInt(tags.group(1))))
            {
                accountIcons.append(tags.group());
            }
        }

        String plainName = IMG_TAG.matcher(name).replaceAll("");

        return rankIconTags(plainName) + accountIcons + plainName;
    }

    public boolean showsRankIcon(String text)
    {
        Matcher tags = IMG_TAG.matcher(text);
        while (tags.find())
        {
            int index = Integer.parseInt(tags.group(1));
            for (RankIcon icon : icons.values())
            {
                if (chatIconManager.chatIconIndex(icon.iconId) == index)
                {
                    return true;
                }
            }
        }
        return false;
    }

    RankSlot rankSlot(String name)
    {
        List<RankIcon> shown = new ArrayList<>();
        StringBuilder key = new StringBuilder();
        StringBuffer nameWithoutRankIcons = new StringBuffer();
        Matcher tags = IMG_TAG.matcher(name);
        while (tags.find())
        {
            RankIcon icon = iconAtChatIndex(Integer.parseInt(tags.group(1)));
            if (icon != null)
            {
                shown.add(icon);
                key.append(icon.iconId).append(',');
                tags.appendReplacement(nameWithoutRankIcons, "");
            }
        }
        if (shown.isEmpty())
        {
            return null;
        }
        tags.appendTail(nameWithoutRankIcons);

        RankSlotSprite slot = rankSlotSprites.computeIfAbsent(key.toString(), iconIds -> new RankSlotSprite(shown));
        return new RankSlot(currentSpriteId(slot), slot.width, slot.height, nameWithoutRankIcons.toString());
    }

    private static int widestFrame(RankIcon icon)
    {
        int widest = 0;
        for (BufferedImage image : icon.images)
        {
            widest = Math.max(widest, image.getWidth());
        }
        return widest;
    }

    private void showCurrentRankSlotFrames(List<RankIcon> advanced)
    {
        Map<Integer, Integer> currentSpriteIdByShownId = new HashMap<>();
        for (RankSlotSprite slot : rankSlotSprites.values())
        {
            if (slot.icons.stream().noneMatch(advanced::contains))
            {
                continue;
            }

            int current = currentSpriteId(slot);
            for (int spriteId : slot.spriteIdsByFrames.values())
            {
                if (spriteId != current)
                {
                    currentSpriteIdByShownId.put(spriteId, current);
                }
            }
        }
        if (currentSpriteIdByShownId.isEmpty())
        {
            return;
        }

        Widget chatLines = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
        Widget[] children = chatLines == null ? null : chatLines.getChildren();
        if (children == null)
        {
            return;
        }

        for (Widget child : children)
        {
            if (child == null || child.getType() != WidgetType.GRAPHIC)
            {
                continue;
            }

            Integer current = currentSpriteIdByShownId.get(child.getSpriteId());
            if (current != null)
            {
                child.setSpriteId(current);
            }
        }
    }

    private int currentSpriteId(RankSlotSprite slot)
    {
        StringBuilder frames = new StringBuilder();
        for (RankIcon icon : slot.icons)
        {
            frames.append(icon.frame).append(',');
        }

        Integer spriteId = slot.spriteIdsByFrames.get(frames.toString());
        if (spriteId == null)
        {
            spriteId = nextRankSlotSpriteId--;
            client.getSpriteOverrides().put(spriteId, drawRankSlot(slot));
            slot.spriteIdsByFrames.put(frames.toString(), spriteId);
        }
        return spriteId;
    }

    private RankIcon iconAtChatIndex(int index)
    {
        for (RankIcon icon : icons.values())
        {
            if (chatIconManager.chatIconIndex(icon.iconId) == index)
            {
                return icon;
            }
        }
        return null;
    }

    private SpritePixels drawRankSlot(RankSlotSprite slot)
    {
        BufferedImage combined = new BufferedImage(slot.width, slot.height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = combined.createGraphics();
        int x = 0;
        for (RankIcon icon : slot.icons)
        {
            BufferedImage image = icon.images.get(icon.frame);
            graphics.drawImage(image, x, (slot.height - image.getHeight()) / 2, null);
            x += widestFrame(icon);
        }
        graphics.dispose();

        return ImageUtil.getImageSpritePixels(combined, client);
    }

    private void clearRankSlots()
    {
        for (RankSlotSprite slot : rankSlotSprites.values())
        {
            for (int spriteId : slot.spriteIdsByFrames.values())
            {
                client.getSpriteOverrides().remove(spriteId);
            }
        }
        rankSlotSprites.clear();
        nextRankSlotSpriteId = RANK_SLOT_FIRST_SPRITE_ID;
        NodeCache widgetSpriteCache = client.getWidgetSpriteCache();
        if (widgetSpriteCache != null)
        {
            widgetSpriteCache.reset();
        }
    }

    public String rankIconTags(String name)
    {
        StringBuilder tags = new StringBuilder();
        String plainName = Text.removeTags(name);
        List<String> ranks = members.get(normaliseName(plainName));
        if (ranks == null && isValianceGuest(plainName))
        {
            ranks = GUEST_RANKS;
        }
        if (ranks != null)
        {
            for (String rank : ranks)
            {
                RankIcon icon = icons.get(rank);
                if (icon != null)
                {
                    tags.append("<img=").append(chatIconManager.chatIconIndex(icon.iconId)).append('>');
                }
            }
        }
        return tags.toString();
    }

    private boolean isValianceGuest(String name)
    {
        return isGuestIn(client.getClanChannel(), name) || isGuestIn(client.getGuestClanChannel(), name);
    }

    private static boolean isGuestIn(ClanChannel channel, String name)
    {
        if (!ClanChatService.isValiance(channel))
        {
            return false;
        }

        ClanChannelMember member = channel.findMember(name);
        return member != null && ClanRank.GUEST.equals(member.getRank());
    }

    public int getRanksRevision()
    {
        return ranksRevision;
    }

    static String normaliseName(String name)
    {
        return NAME_SPACING.matcher(name).replaceAll(" ").trim().toLowerCase(Locale.ROOT);
    }
}

package com.encryptiron.chat;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

import javax.inject.Inject;
import javax.inject.Singleton;

import com.encryptiron.ServerAddress;
import com.encryptiron.ValianceConfig;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

@Slf4j
@Singleton
public class ValianceSocket
{
    private static final String PATH = "/api/plugin/ws";
    private static final int NORMAL_CLOSURE = 1000;
    private static final int FIRST_NEVER_RETRY_CLOSE_CODE = 4000;
    private static final int LAST_NEVER_RETRY_CLOSE_CODE = 4099;
    private static final int MAX_QUEUED_MESSAGES = 50;
    private static final long PING_INTERVAL_SECONDS = 30;
    private static final int MAX_BACKOFF_EXPONENT = 6;
    private static final long MAX_RECONNECT_JITTER_MS = 5000;

    @Inject
    private OkHttpClient httpClient;

    @Inject
    private Gson gson;

    @Inject
    private ScheduledExecutorService executor;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ValianceConfig config;

    private final Map<String, Consumer<JsonObject>> handlers = new ConcurrentHashMap<>();

    private OkHttpClient socketClient;
    private WebSocket webSocket;
    private boolean running;
    private boolean connected;
    private JsonObject handshake;
    private final Deque<String> pendingMessages = new ArrayDeque<>();
    private int failedAttempts;
    private ScheduledFuture<?> pendingReconnect;

    public void setHandler(String type, Consumer<JsonObject> handler)
    {
        handlers.put(type, handler);
    }

    public synchronized boolean isRunning()
    {
        return running;
    }

    public synchronized void start(JsonObject handshakeMessage)
    {
        if (running)
        {
            return;
        }

        running = true;
        handshake = handshakeMessage;
        failedAttempts = 0;
        connect();
    }

    public synchronized void stop()
    {
        running = false;
        handshake = null;
        pendingMessages.clear();
        connected = false;

        if (pendingReconnect != null)
        {
            pendingReconnect.cancel(false);
            pendingReconnect = null;
        }

        if (webSocket != null)
        {
            webSocket.close(NORMAL_CLOSURE, null);
            webSocket = null;
        }
    }

    public synchronized void send(JsonObject message)
    {
        if (!running)
        {
            return;
        }

        String text = gson.toJson(message);
        if (connected && webSocket.send(text))
        {
            return;
        }

        if (pendingMessages.size() >= MAX_QUEUED_MESSAGES)
        {
            pendingMessages.removeFirst();
        }
        pendingMessages.addLast(text);
    }

    private void connect()
    {
        if (socketClient == null)
        {
            socketClient = httpClient.newBuilder()
                .pingInterval(PING_INTERVAL_SECONDS, TimeUnit.SECONDS)
                .build();
        }

        Request request = new Request.Builder()
            .url(ServerAddress.webSocketUrl(config.valianceServerUrl(), PATH))
            .header("User-Agent", "ValiancePlugin")
            .build();

        webSocket = socketClient.newWebSocket(request, new Listener());
    }

    private synchronized void onOpened(WebSocket socket)
    {
        if (socket != webSocket)
        {
            return;
        }

        connected = true;
        failedAttempts = 0;
        socket.send(gson.toJson(handshake));

        while (!pendingMessages.isEmpty())
        {
            if (!socket.send(pendingMessages.peekFirst()))
            {
                break;
            }
            pendingMessages.removeFirst();
        }
    }

    private void onReceived(WebSocket socket, String text)
    {
        JsonObject message;
        synchronized (this)
        {
            if (socket != webSocket)
            {
                return;
            }

            try
            {
                message = gson.fromJson(text, JsonObject.class);
            }
            catch (JsonParseException ex)
            {
                log.debug("Ignoring unreadable message from the Valiance server", ex);
                return;
            }

            if (message == null)
            {
                return;
            }

            if ("welcome".equals(getString(message, "type")) && running)
            {
                handshake.remove("history");
            }
        }

        Consumer<JsonObject> handler = handlers.get(getString(message, "type"));
        if (handler != null)
        {
            clientThread.invokeLater(() -> handler.accept(message));
        }
    }

    private synchronized void onDisconnected(WebSocket socket, int code)
    {
        if (socket != webSocket)
        {
            return;
        }

        webSocket = null;
        connected = false;

        if (!running)
        {
            return;
        }

        if (code >= FIRST_NEVER_RETRY_CLOSE_CODE && code <= LAST_NEVER_RETRY_CLOSE_CODE)
        {
            log.warn("The Valiance server refused the connection ({})", code);
            running = false;
            handshake = null;
            pendingMessages.clear();
            return;
        }

        long delayMs = TimeUnit.SECONDS.toMillis(1L << Math.min(failedAttempts, MAX_BACKOFF_EXPONENT))
            + ThreadLocalRandom.current().nextLong(MAX_RECONNECT_JITTER_MS + 1);
        failedAttempts++;
        pendingReconnect = executor.schedule(this::reconnect, delayMs, TimeUnit.MILLISECONDS);
    }

    private synchronized void reconnect()
    {
        pendingReconnect = null;
        if (running && webSocket == null)
        {
            connect();
        }
    }

    static String getString(JsonObject json, String key)
    {
        JsonElement element = json.get(key);
        return element != null && element.isJsonPrimitive() ? element.getAsString() : null;
    }

    private class Listener extends WebSocketListener
    {
        @Override
        public void onOpen(WebSocket socket, Response response)
        {
            onOpened(socket);
        }

        @Override
        public void onMessage(WebSocket socket, String text)
        {
            onReceived(socket, text);
        }

        @Override
        public void onClosing(WebSocket socket, int code, String reason)
        {
            socket.close(NORMAL_CLOSURE, null);
            onDisconnected(socket, code);
        }

        @Override
        public void onClosed(WebSocket socket, int code, String reason)
        {
            onDisconnected(socket, code);
        }

        @Override
        public void onFailure(WebSocket socket, Throwable t, Response response)
        {
            log.debug("Lost the connection to the Valiance server", t);
            onDisconnected(socket, -1);
        }
    }
}

package com.encryptiron.rest;

import java.io.IOException;
import java.net.MalformedURLException;
import java.net.URI;
import java.net.URISyntaxException;
import java.net.URL;

import javax.inject.Inject;

import com.encryptiron.PopUpQueue;
import com.encryptiron.ServerAddress;
import com.encryptiron.ValianceConfig;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.RuneScapeProfileType;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Request.Builder;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

@Slf4j
public abstract class BaseRestCommand {
    private static final MediaType APPLICATION_JSON = MediaType.parse("application/json");
    protected static final String SERVER_SUCCESS_MESSAGE = "Success";

    @Inject
    private OkHttpClient httpClient;

    @Inject
    public ValianceConfig config;

    @Inject
    public Client client;

    @Inject
    public ClientThread clientThread;

    @Inject
    private PopUpQueue popUpQueue;

    private void writeMessageToServer(JsonObject body)
    {
        URL url;
        try
        {
            url = new URI(ServerAddress.httpUrl(config.valianceServerUrl(), endpoint())).toURL();
        } catch (MalformedURLException | URISyntaxException e)
        {
            log.error("MalformedURL : " + e.getMessage());
            return;
        }

        RequestBody requestBody = RequestBody.create(APPLICATION_JSON, body.toString());

        Request httpRequest = new Builder()
            .url(url)
            .header("User-Agent", "ValiancePlugin - " + body.getAsJsonObject("header").get("player_name").getAsString())
            .post(requestBody)
            .build();

        httpClient.newCall(httpRequest).enqueue(new Callback() 
        {
            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (ResponseBody responseBody = response.body())
                {
                    if (!response.isSuccessful())
                    {
                        clientThread.invokeLater(() -> {
                            onFailCodeResponse(httpRequest, response);
                        });
                    }
                    else
                    {
                        String bodyString = responseBody.string();

                        // Our responses are normally not JSON,
                        // but if they are, we want the client to do something in response
                        try
                        {
                            JsonParser parser = new JsonParser();
                            JsonObject json = parser.parse(bodyString).getAsJsonObject();

                            clientThread.invokeLater(() -> {
                                onJsonResponse(httpRequest, json);
                            });
                        }
                        catch (Exception ex)
                        {
                            clientThread.invokeLater(() -> {
                                onTextResponse(httpRequest, bodyString);
                            });
                        }
                    }
                }
            }

            @Override
            public void onFailure(Call call, IOException e) {
                clientThread.invokeLater(() -> {
                    onRequestFailed(httpRequest, e);
                });
            }
        });
    }

    public void send()
    {
        // Prepare the body outside of the thread, in case there are any delays
        JsonObject body = body();

        if (MessageHeaderData.getPlayerName() == null)
        {
            // The player hasn't fully logged in yet, this means this message is the server catching us up
            // on what the player has, after login / hop. We can skip sending this message as we don't care about it.
            return;
        }

        MessageHeaderData.setProfileType(RuneScapeProfileType.getCurrent(client));
        body.add("header", MessageHeaderData.getMessageHeaderJson());

        // We want to send the message in a separate thread so that we 
        // don't block the game client while waiting for the response
        Thread sendThread = new Thread(() -> {
            writeMessageToServer(body);
        });

        sendThread.start();
    }

    abstract String requestType();
    abstract String endpoint();
    abstract JsonObject body();
    abstract String onRequestFailedMessage();
    // Server responds with OK and a successful response
    abstract String onSuccessResponseMessage();
    // Server responds with OK but something might be off, let the user know
    private String onTextResponseMessage(String serverResponse) {
        return "Valiance Server: " + serverResponse;
    }

    public void onJsonResponse(Request request, JsonObject json)
    {
        log.debug("Received json response: " + json.toString());

        showServerMessages(json);

        // The parent class should override this function if they want to do something with the response
    }

    private void showServerMessages(JsonObject json)
    {
        if (!json.has("messages") || !json.get("messages").isJsonArray())
        {
            showServerMessage(json);
            return;
        }

        for (JsonElement message : json.getAsJsonArray("messages"))
        {
            if (message.isJsonObject())
            {
                showServerMessage(message.getAsJsonObject());
            }
        }
    }

    private void showServerMessage(JsonObject message)
    {
        showServerPopUp(message);
        showServerChatMessage(message);
    }

    private void showServerPopUp(JsonObject json)
    {
        if (!config.popupOnEventItemAccepted() || !hasServerPopUp(json))
        {
            return;
        }

        JsonObject popUp = json.getAsJsonObject("popUp");
        if (popUp.has("title") && popUp.has("description"))
        {
            sendPopUp(popUp.get("title").getAsString(), popUp.get("description").getAsString());
        }
    }

    private boolean hasServerPopUp(JsonObject json)
    {
        return json != null && json.has("popUp") && json.get("popUp").isJsonObject();
    }

    private void showServerChatMessage(JsonObject json)
    {
        if (!config.chatMessageOnEventItemAccepted() || !hasServerChatMessage(json))
        {
            return;
        }

        JsonObject chatMessage = json.getAsJsonObject("chatMessage");
        if (chatMessage.has("title") && chatMessage.has("message"))
        {
            String title = chatMessage.get("title").getAsString();
            String eventChatMessage = "[<col=5555FF>" + title + "</col>] <col=ff0000>"
                    + chatMessage.get("message").getAsString() + "</col>";
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "ValianceCC", eventChatMessage, title);
        }
    }

    private boolean hasServerChatMessage(JsonObject json)
    {
        return json != null && json.has("chatMessage") && json.get("chatMessage").isJsonObject();
    }

    public void onTextResponse(Request request, String response)
    {
        log.debug("Received text response: " + response);

        if (!config.debug())
            return;

        if (response.equals(SERVER_SUCCESS_MESSAGE))
        {
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", onSuccessResponseMessage(), "ValianceClanPlugin");
        }
        else
        {
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", onTextResponseMessage(response), "ValianceClanPlugin");
        }
    }

    public void onFailCodeResponse(Request request, Response response)
    {
        log.warn("Received failed code response from " + request.url().encodedPath() + ": " + response.code());

        try
        {
            // If we sent back an error, let's print it for debug purposes.
            String bodyString = response.body().string();            
            JsonParser parser = new JsonParser();
            JsonObject json = parser.parse(bodyString).getAsJsonObject();
            String error = json.get("string").getAsString();

            log.warn("Error received when sending message: " + error);
        }
        catch(Exception ex)
        {
            // Json parsing error, no error given
        }

        sendFailMessage();
    }

    public void onRequestFailed(Request request, IOException exception)
    {
        log.warn("Failed to send request to " + request.url().encodedPath() + ": " + exception.getMessage());
        sendFailMessage();
    }

    public void sendFailMessage()
    {
        if (!config.debug())
            return;

        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", onRequestFailedMessage(), "ValianceClanPlugin");
    }

    public void sendPopUp(String title, String description)
    {
        popUpQueue.add(title, description);
    }

    protected boolean isResponseType(JsonObject json, String type)
    {
        return json != null && json.has("type") && type.equals(json.get("type").getAsString());
    }
}

package com.encryptiron.rest;

public abstract class GetCommand extends BaseRestCommand {
    @Override
    String requestType()
    {
        return "GET";
    }
}

package com.encryptiron.rest;

import java.time.Instant;

import com.google.gson.JsonObject;

import lombok.Getter;
import lombok.Setter;
import net.runelite.client.config.RuneScapeProfileType;

public final class MessageHeaderData 
{
    @Getter
    @Setter
    private static String playerName = null;

    @Getter
    @Setter
    private static RuneScapeProfileType profileType = null;

    @Getter
    @Setter
    private static Long accountId = null;

    @Getter
    @Setter
    private static Integer accountType = null;

    public static void reset()
    {
        MessageHeaderData.accountId = null;
        MessageHeaderData.accountType = null;
        MessageHeaderData.playerName = null;
    }

    public static JsonObject getMessageHeaderJson()
    {
        JsonObject headerData = new JsonObject();
        headerData.addProperty("account_id", getAccountId());
        headerData.addProperty("account_type", getAccountType());
        headerData.addProperty("player_name", getPlayerName());
        headerData.addProperty("profile_type", getProfileType().name());
        headerData.addProperty("time", Instant.now().toEpochMilli());

        return headerData;
    }
}

package com.encryptiron.rest;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.Subscribe;

import com.google.gson.JsonObject;

import net.runelite.api.events.VarbitChanged;

@Slf4j
public class NewCollectionLogEntry extends PostCommand
{
    public int collectionLogEntryId = 0;
    private int lastKnownCollectionLogEntryId = 0;

    @Override
    String endpoint() {
        return "/api/member/new_collection_log";
    }

    @Override
    JsonObject body()
    {
        JsonObject json = new JsonObject();
        json.addProperty("itemId", collectionLogEntryId);

        return json;
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN ||
            event.getGameState() == GameState.HOPPING)
		{
            lastKnownCollectionLogEntryId = 0;
		}
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged varbitChanged)
    {
        // On log-in the game sends:
        // Varbit 4623 = 0
        // Varbit 4623 = <our last clog>
        // Varbit 4623 = <new clog> (when we get one)

        if (varbitChanged.getVarpId() == 4623)
        {
            int itemId = client.getVarpValue(varbitChanged.getVarpId());

            if (itemId == 0)
            {
                // The first pass on log-in
                return;
            }

            if (lastKnownCollectionLogEntryId == 0)
            {
                // On log-in, we load the last clog we've had, so this isn't actually a new clog.
                // Let's ignore it
                lastKnownCollectionLogEntryId = itemId;
                return;
            }

            lastKnownCollectionLogEntryId = itemId;

            if (lastKnownCollectionLogEntryId > 0)
            {
                collectionLogEntryId = lastKnownCollectionLogEntryId;
                send();
            }
        }

    }

    @Override
    String onRequestFailedMessage()
    {
        return "Failed to send the newly obtained collection log item to the Valiance server.";
    }

    @Override
    String onSuccessResponseMessage()
    {
        return "Sent the newly obtained collection log item to the Valiance server!";
    }
}

