package com.encryptiron.boards;

import static org.junit.Assert.assertEquals;

import java.util.List;

import org.junit.Before;
import org.junit.Test;

import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ObjectID;

public class BrutusBoardReaderTest
{
    private static final String BRUTUS_SENT = "Brutus|Any||0:01.20";
    private static final String DEMONIC_SENT = "Demonic Brutus|Any||3:10.20";

    private final FakeGame game = new FakeGame();
    private final BrutusBoardReader reader = new BrutusBoardReader(game.client, game.boardTimesSender);

    @Before
    public void setKillCounts()
    {
        game.varps.put(5407, 1542);
        game.varps.put(5408, 1);
    }

    private void clickRead()
    {
        reader.onMenuOptionClicked(FakeGame.click(MenuAction.GAME_OBJECT_FIRST_OPTION, ObjectID.COWBOSS_SCOREBOARD_MULTI));
    }

    private void clickReadDemonic()
    {
        reader.onMenuOptionClicked(FakeGame.click(MenuAction.GAME_OBJECT_SECOND_OPTION, ObjectID.COWBOSS_SCOREBOARD_MULTI));
    }

    private void boardOpens(String killCount, String time)
    {
        game.textByComponent.put(InterfaceID.CowbossScoreboard.PKC_CONTENT, killCount);
        game.textByComponent.put(InterfaceID.CowbossScoreboard.PBT_CONTENT, time);
        reader.onWidgetLoaded(game.open(InterfaceID.COWBOSS_SCOREBOARD));
        reader.onGameTick(new GameTick());
    }

    private void brutusBoardOpens()
    {
        boardOpens("1,542", "0:01.20");
    }

    private void demonicBoardOpens()
    {
        boardOpens("1", "3:10.20");
    }

    @Test
    public void namesTheBossByTheOptionClicked()
    {
        clickRead();
        game.tick += 2;
        brutusBoardOpens();
        assertEquals(List.of(BRUTUS_SENT), game.sentTimes());
    }

    @Test
    public void readsADemonicBoardAfterALongWalk()
    {
        clickReadDemonic();
        game.tick += 40;
        demonicBoardOpens();
        assertEquals(List.of(DEMONIC_SENT), game.sentTimes());
    }

    @Test
    public void sendsNothingWhenTheOptionWasSwitchedBeforeTheBoardOpened()
    {
        clickRead();
        clickReadDemonic();
        game.tick += 1;
        brutusBoardOpens();
        game.tick += 1;
        demonicBoardOpens();
        assertEquals(List.of(), game.sentTimes());
    }

    @Test
    public void sendsNothingWhenAnOlderClickWasNeverAnswered()
    {
        clickRead();
        game.tick += 30;
        clickReadDemonic();
        game.tick += 1;
        demonicBoardOpens();
        assertEquals(List.of(), game.sentTimes());

        game.tick += 20;
        clickReadDemonic();
        game.tick += 1;
        demonicBoardOpens();
        assertEquals(List.of(DEMONIC_SENT), game.sentTimes());
    }

    @Test
    public void readsTheOtherBoardOnlyOnceTheFirstClickIsOldEnough()
    {
        clickRead();
        game.tick += 1;
        brutusBoardOpens();
        game.tick += 5;
        clickReadDemonic();
        game.tick += 1;
        demonicBoardOpens();
        assertEquals(List.of(BRUTUS_SENT), game.sentTimes());

        game.tick += 4;
        clickReadDemonic();
        game.tick += 1;
        demonicBoardOpens();
        assertEquals(List.of(BRUTUS_SENT, DEMONIC_SENT), game.sentTimes());
    }

    @Test
    public void sendsNothingWhenTheKillCountIsNotThatBosss()
    {
        clickRead();
        demonicBoardOpens();
        assertEquals(List.of(), game.sentTimes());
    }

    @Test
    public void sendsNothingWithoutAClick()
    {
        brutusBoardOpens();
        assertEquals(List.of(), game.sentTimes());
    }

    @Test
    public void forgetsClicksOnHopping()
    {
        clickRead();
        GameStateChanged hopping = new GameStateChanged();
        hopping.setGameState(GameState.HOPPING);
        reader.onGameStateChanged(hopping);
        brutusBoardOpens();
        assertEquals(List.of(), game.sentTimes());
    }

    @Test
    public void ignoresOtherObjects()
    {
        reader.onMenuOptionClicked(FakeGame.click(MenuAction.GAME_OBJECT_FIRST_OPTION, 1));
        brutusBoardOpens();
        assertEquals(List.of(), game.sentTimes());
    }
}

package com.encryptiron.boards;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import com.encryptiron.rest.SendBoardTimes;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.ScriptEvent;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.widgets.Widget;

class FakeGame
{
    final Map<Integer, String> textByComponent = new HashMap<>();
    final Set<Integer> hiddenComponents = new HashSet<>();
    final Map<Integer, Integer> varbits = new HashMap<>();
    final Map<Integer, Integer> varps = new HashMap<>();
    final Set<Integer> openInterfaces = new HashSet<>();
    final List<JsonArray> sent = new ArrayList<>();
    int tick;

    final Client client = fake(Client.class, (proxy, method, arguments) -> {
        switch (method.getName())
        {
            case "getWidget":
                return arguments.length == 2
                    ? (openInterfaces.contains(arguments[0]) ? widget("", false) : null)
                    : widgetOf((Integer) arguments[0]);
            case "getVarbitValue":
                return varbits.getOrDefault(arguments[0], 0);
            case "getVarpValue":
                return varps.getOrDefault(arguments[0], 0);
            case "getTickCount":
                return tick;
            default:
                throw new UnsupportedOperationException(method.getName());
        }
    });

    final BoardTimesSender boardTimesSender = new BoardTimesSender(new SendBoardTimes()
    {
        @Override
        public void send(JsonArray times)
        {
            sent.add(times);
        }
    });

    WidgetLoaded open(int interfaceId)
    {
        openInterfaces.add(interfaceId);
        WidgetLoaded widgetLoaded = new WidgetLoaded();
        widgetLoaded.setGroupId(interfaceId);
        return widgetLoaded;
    }

    static ScriptPreFired script(Object... arguments)
    {
        ScriptPreFired scriptPreFired = new ScriptPreFired((Integer) arguments[0]);
        scriptPreFired.setScriptEvent(fake(ScriptEvent.class, (proxy, method, unused) -> arguments));
        return scriptPreFired;
    }

    static MenuOptionClicked click(MenuAction menuAction, int objectId)
    {
        return new MenuOptionClicked(fake(MenuEntry.class, (proxy, method, unused) ->
            method.getName().equals("getType") ? menuAction : objectId));
    }

    List<String> sentTimes()
    {
        List<String> times = new ArrayList<>();
        for (JsonArray sentArray : sent)
        {
            for (JsonElement element : sentArray)
            {
                JsonObject time = element.getAsJsonObject();
                times.add(time.get("content").getAsString() + "|" + time.get("team_size").getAsString() + "|"
                    + time.get("split").getAsString() + "|"
                    + (time.has("ticks") ? time.get("ticks").getAsInt() + " ticks" : time.get("time").getAsString()));
            }
        }
        return times;
    }

    private Widget widgetOf(int componentId)
    {
        return openInterfaces.contains(componentId >>> 16)
            ? widget(textByComponent.getOrDefault(componentId, "-"), hiddenComponents.contains(componentId))
            : null;
    }

    private static Widget widget(String text, boolean hidden)
    {
        return fake(Widget.class, (proxy, method, arguments) -> method.getName().equals("isHidden") ? (Object) hidden : text);
    }

    private static <T> T fake(Class<T> type, InvocationHandler handler)
    {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[] {type}, handler));
    }
}

package com.encryptiron.boards;

import static org.junit.Assert.assertEquals;

import java.util.List;

import org.junit.Test;

import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InterfaceID.ToaScoreboard;
import net.runelite.api.gameval.InterfaceID.TobScoreboard;

public class RaidBoardReaderTest
{
    private static final int TOB_TAB = 12270;
    private static final int TOA_TAB = 14320;
    private static final int NORMAL = 0;
    private static final int ENTRY = 1;
    private static final int HARD = 2;

    private final FakeGame game = new FakeGame();
    private final RaidBoardReader reader = new RaidBoardReader(game.client, game.boardTimesSender);

    private void tick()
    {
        reader.onGameTick(new GameTick());
    }

    private void clickTobTab(int tab)
    {
        reader.onScriptPreFired(FakeGame.script(4493, 23789572, 23789573, 23789574, tab));
        game.varbits.put(TOB_TAB, tab);
    }

    private void serverOpensTob(String threePlayerChallenge)
    {
        game.textByComponent.put(TobScoreboard.DATA_3MAN_P_R, threePlayerChallenge);
        reader.onWidgetLoaded(game.open(InterfaceID.TOB_SCOREBOARD));
    }

    @Test
    public void readsChallengeAndOverallTimesPerTeamSize()
    {
        game.varbits.put(TOB_TAB, HARD);
        game.textByComponent.put(TobScoreboard.DATA_SOLO_P_R, "25:00.00");
        game.textByComponent.put(TobScoreboard.DATA_5MAN_P_R, "18:00.60");
        game.textByComponent.put(TobScoreboard.DATA_5MAN_P_O, "20:15.00");
        game.textByComponent.put(TobScoreboard.DATA_5MAN_G_R, "14:00.00");
        reader.onWidgetLoaded(game.open(InterfaceID.TOB_SCOREBOARD));
        tick();
        assertEquals(List.of(
            "Theatre of Blood: Hard Mode|Solo||25:00.00",
            "Theatre of Blood: Hard Mode|5 players||18:00.60",
            "Theatre of Blood: Hard Mode|5 players|Overall time|20:15.00"), game.sentTimes());
    }

    @Test
    public void readsTombsModesUpToEightPlayers()
    {
        game.varbits.put(TOA_TAB, 2);
        game.textByComponent.put(ToaScoreboard.DATA_8MAN_P_R, "15:00.00");
        game.textByComponent.put(ToaScoreboard.DATA_8MAN_P_O, "17:30.00");
        reader.onWidgetLoaded(game.open(InterfaceID.TOA_SCOREBOARD));
        tick();
        assertEquals(List.of(
            "Tombs of Amascut: Expert Mode|8 players||15:00.00",
            "Tombs of Amascut: Expert Mode|8 players|Overall time|17:30.00"), game.sentTimes());
    }

    @Test
    public void neverReadsTheOldTimesBetweenATabClickAndTheBoardReopening()
    {
        game.varbits.put(TOB_TAB, ENTRY);
        serverOpensTob("18:10.20");
        tick();
        clickTobTab(NORMAL);
        tick();
        serverOpensTob("17:24.60");
        tick();
        assertEquals(List.of("Theatre of Blood: Entry Mode|3 players||18:10.20", "Theatre of Blood|3 players||17:24.60"), game.sentTimes());
    }

    @Test
    public void readsNothingMoreUntilClosedAfterTwoClicksBeforeTheBoardReopened()
    {
        game.varbits.put(TOB_TAB, NORMAL);
        serverOpensTob("17:24.60");
        tick();
        clickTobTab(ENTRY);
        clickTobTab(HARD);
        serverOpensTob("18:10.20");
        tick();
        serverOpensTob("20:00.00");
        tick();
        assertEquals(List.of("Theatre of Blood|3 players||17:24.60"), game.sentTimes());

        game.openInterfaces.clear();
        tick();
        serverOpensTob("20:00.00");
        tick();
        assertEquals(List.of("Theatre of Blood|3 players||17:24.60", "Theatre of Blood: Hard Mode|3 players||20:00.00"), game.sentTimes());
    }

    @Test
    public void cancelsAReadWhenATabIsClickedBeforeTheTickEnds()
    {
        game.varbits.put(TOB_TAB, NORMAL);
        serverOpensTob("17:24.60");
        clickTobTab(ENTRY);
        tick();
        assertEquals(List.of(), game.sentTimes());

        serverOpensTob("18:10.20");
        tick();
        assertEquals(List.of("Theatre of Blood: Entry Mode|3 players||18:10.20"), game.sentTimes());
    }

    @Test
    public void clickingTheSelectedTabChangesNothing()
    {
        game.varbits.put(TOB_TAB, NORMAL);
        serverOpensTob("17:24.60");
        clickTobTab(NORMAL);
        clickTobTab(NORMAL);
        tick();
        assertEquals(List.of("Theatre of Blood|3 players||17:24.60"), game.sentTimes());
    }

    @Test
    public void sendsNothingForAnUnknownMode()
    {
        game.varbits.put(TOB_TAB, 5);
        serverOpensTob("17:24.60");
        tick();
        assertEquals(List.of(), game.sentTimes());
    }
}

package com.encryptiron.boards;

